[{"order":1,"type":"heading","text":"JSON Web Tokens (JWT) in Node.js: A Comprehensive Guide"},{"order":2,"type":"paragraph","text":"JSON Web Tokens (JWTs) are a standard for securely transmitting information between parties as a JSON object. This tutorial will guide you through creating, verifying, and using JWTs in a Node.js application."},{"order":3,"type":"subheading","text":"Prerequisites"},{"order":4,"type":"bullet_point","text":"Node.js and npm installed on your machine."},{"order":5,"type":"bullet_point","text":"Basic understanding of JavaScript and Node.js."},{"order":6,"type":"subheading","text":"Setting up the Project"},{"order":7,"type":"paragraph","text":"Create a new directory for your project and initialize a Node.js project:"},{"order":8,"type":"code","text":"mkdir node-jwt-tutorial
cd node-jwt-tutorial
npm init -y"},{"order":9,"type":"paragraph","text":"Install the 'jsonwebtoken' package:"},{"order":10,"type":"code","text":"npm install jsonwebtoken"},{"order":11,"type":"subheading","text":"Creating a JWT"},{"order":12,"type":"paragraph","text":"Create a file named 'auth.js'. This file will contain the functions for creating and verifying JWTs."},{"order":13,"type":"code","text":"// auth.js
const jwt = require('jsonwebtoken');

const secretKey = 'your-secret-key'; // Replace with a strong, secret key

function generateToken(payload) {
  return jwt.sign(payload, secretKey, { expiresIn: '1h' }); // Token expires in 1 hour
}

module.exports = { generateToken, secretKey };"},{"order":14,"type":"paragraph","text":"Explanation:
- 'jsonwebtoken' is the library used for JWT operations.
- 'secretKey' is a secret string used to sign the token.  **Important:** Replace 'your-secret-key' with a strong, randomly generated secret in a real application. Store this securely (e.g., environment variable).
- 'generateToken' function takes a 'payload' (an object containing user data) and returns a signed JWT. The 'expiresIn' option sets the token's expiration time."},{"order":15,"type":"subheading","text":"Verifying a JWT"},{"order":16,"type":"paragraph","text":"Add a function to 'auth.js' to verify the JWT:"},{"order":17,"type":"code","text":"// auth.js (add this to the existing file)

function verifyToken(token) {
  try {
    const decoded = jwt.verify(token, secretKey);
    return decoded;
  } catch (error) {
    return null; // Token is invalid or expired
  }
}

module.exports = { generateToken, verifyToken, secretKey };"},{"order":18,"type":"paragraph","text":"Explanation:
- 'verifyToken' function takes a JWT as input.
- 'jwt.verify' attempts to decode and verify the token using the 'secretKey'.
- If the token is valid, it returns the decoded payload. Otherwise, it returns 'null'."},{"order":19,"type":"subheading","text":"Using JWTs in an API Endpoint"},{"order":20,"type":"paragraph","text":"Create a file named 'app.js' to simulate an API endpoint that uses JWTs for authentication."},{"order":21,"type":"code","text":"// app.js
const express = require('express');
const { generateToken, verifyToken } = require('./auth');

const app = express();
const port = 3000;

app.use(express.json()); // Middleware to parse JSON bodies

app.post('/login', (req, res) => {
  // Simulate user authentication (replace with actual authentication logic)
  const { username, password } = req.body;
  if (username === 'testuser' && password === 'password') {
    const payload = { userId: 123, username: username };
    const token = generateToken(payload);
    res.json({ token: token });
  } else {
    res.status(401).json({ message: 'Invalid credentials' });
  }
});

app.get('/protected', (req, res) => {
  const token = req.headers.authorization?.split(' ')[1]; // Extract token from Authorization header

  if (!token) {
    return res.status(401).json({ message: 'No token provided' });
  }

  const decoded = verifyToken(token);

  if (!decoded) {
    return res.status(401).json({ message: 'Invalid token' });
  }

  // Token is valid, access granted
  res.json({ message: 'Protected resource accessed', user: decoded });
});

app.listen(port, () => {
  console.log(`Server listening on port ${port}`);
});"},{"order":22,"type":"paragraph","text":"Explanation:
- '/login' endpoint: Simulates user login. If credentials are valid, it generates a JWT and returns it to the client.
- '/protected' endpoint: Requires a valid JWT in the 'Authorization' header. It verifies the token and, if valid, returns a protected resource.  The 'Authorization' header is expected to be in the format 'Bearer <token>'."},{"order":23,"type":"subheading","text":"Running the Application"},{"order":24,"type":"paragraph","text":"Run the application using:"},{"order":25,"type":"code","text":"node app.js"},{"order":26,"type":"subheading","text":"Testing the Endpoints"},{"order":27,"type":"paragraph","text":"1. **Login:** Send a POST request to '/login' with the following JSON body:"},{"order":28,"type":"code","text":"{
  "username": "testuser",
  "password": "password"
}"},{"order":29,"type":"paragraph","text":"This will return a JWT."},{"order":30,"type":"paragraph","text":"2. **Accessing the Protected Resource:** Send a GET request to '/protected' with the 'Authorization' header set to 'Bearer <your_jwt>' (replace '<your_jwt>' with the actual JWT you received from the login endpoint)."},{"order":31,"type":"paragraph","text":"If the token is valid, you will receive a response indicating that you have accessed the protected resource."},{"order":32,"type":"subheading","text":"Important Considerations"},{"order":33,"type":"bullet_point","text":"**Secret Key Security:** Never hardcode the secret key directly into your code. Use environment variables or a secure configuration management system."},{"order":34,"type":"bullet_point","text":"**Token Expiration:** Set appropriate expiration times for your tokens to limit the window of opportunity for attackers to use compromised tokens."},{"order":35,"type":"bullet_point","text":"**Token Storage:** On the client-side, store tokens securely. Avoid storing them in local storage if possible. Consider using HTTP-only cookies or other more secure methods."},{"order":36,"type":"bullet_point","text":"**Refresh Tokens:** Implement refresh tokens to allow users to obtain new access tokens without re-authenticating."},{"order":37,"type":"subheading","text":"Conclusion"},{"order":38,"type":"paragraph","text":"This tutorial provided a basic introduction to creating, verifying, and using JWTs in Node.js. Remember to prioritize security best practices when implementing JWT authentication in your applications."}]
